const expandedCards=new Set(),collapsedCards=new Set();
let data=[],catalogMeta=null,catalogLoaded=false,page=1;const PAGE_SIZE=24;
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>s.normalize('NFKC').toLowerCase().replace(/[’‘]/g,"'").replace(/\s+/g,' ').trim();
function nameMatches(names,query){const q=norm(query).replace(/[\p{P}\p{Z}\s]/gu,'');if(!q)return true;return names.some(name=>{const text=norm(String(name||'')).replace(/[\p{P}\p{Z}\s]/gu,'');let cursor=0;for(const char of q){const at=text.indexOf(char,cursor);if(at<0)return false;cursor=at+char.length;}return true;});}
let saved=[];try{const v=JSON.parse(localStorage.getItem('drama-favs')||'[]');if(Array.isArray(v))saved=v.filter(id=>typeof id==='string'&&/^[A-Za-z0-9_-]{1,200}$/.test(id));}catch{}
let disliked=[],localDisliked=[];try{const v=JSON.parse(localStorage.getItem('drama-dislikes')||'[]');if(Array.isArray(v))localDisliked=v.filter(id=>typeof id==='string'&&/^[A-Za-z0-9_-]{1,200}$/.test(id));disliked=localDisliked.slice();}catch{}
let watchState={},localWatchState={},watchFilter='',watchSaveQueue=Promise.resolve();try{const value=JSON.parse(localStorage.getItem('drama-watchlist')||'{}');if(value&&typeof value==='object'&&!Array.isArray(value))localWatchState=Object.fromEntries(Object.entries(value).filter(([id,status])=>/^[A-Za-z0-9_-]{1,200}$/.test(id)&&['watched','want'].includes(status)));watchState={...localWatchState};}catch{}
function groupWatchStatus(d){return d.members.some(m=>watchState[m.id]==='watched')?'watched':d.members.some(m=>watchState[m.id]==='want')?'want':null;}
function watchButtons(d){const status=groupWatchStatus(d);return `<div class="watch-actions"><button type="button" data-watch="watched" data-watch-group="${d.id}" aria-pressed="${status==='watched'}">${status==='watched'?'✓ 已看':'已看'}</button><button type="button" data-watch="want" data-watch-group="${d.id}" aria-pressed="${status==='want'}">${status==='want'?'✓ 想看':'想看'}</button></div>`;}
let onlyFav=false,counts=null,countsLoaded=false,proposals=[],threshold=2,aliasLoaded=false;
function paintCounts(){document.querySelectorAll('[data-count]').forEach(e=>{e.textContent=counts===null?(countsLoaded?'次数暂不可用':'加载次数…'):(counts[e.dataset.count]||0)+' 次点击';});}
async function refreshCounts(){try{const r=await fetch('/api/counts',{cache:'no-store'});if(!r.ok)throw Error();counts=(await r.json()).counts;}catch{counts=null;}countsLoaded=true;paintCounts();}
function groupedCatalog(){
 const parent=new Map(data.map(d=>[d.id,d.id]));
 function find(id){while(parent.get(id)!==id)id=parent.get(id);return id;}
 const blocks=proposals.filter(p=>p.approved&&p.kind==='split');
 const members=new Map(data.map(d=>[d.id,new Set([d.id])]));
 function unite(left,right){if(!parent.has(left)||!parent.has(right))return;const a=find(left),b=find(right);if(a===b)return;const x=members.get(a),y=members.get(b);if(blocks.some(p=>(x.has(p.left_id)&&y.has(p.right_id))||(x.has(p.right_id)&&y.has(p.left_id))))return;parent.set(b,a);for(const id of y)x.add(id);members.delete(b);}
 const autoRoots=new Map();for(const d of data){const group=d.autoGroup||d.id;if(autoRoots.has(group))unite(autoRoots.get(group),d.id);else autoRoots.set(group,d.id);}
 for(const p of proposals.filter(p=>p.approved&&p.kind==='merge'))unite(p.left_id,p.right_id);
 const groups=new Map();for(const d of data){const root=find(d.id);if(!groups.has(root))groups.set(root,[]);groups.get(root).push(d);}
 return [...groups.values()].map(members=>{const ids=new Set(members.map(d=>d.id));const first=members[0];const names=members.flatMap(d=>[d.title,d.en,...d.aliases]);for(const p of proposals)if(p.approved&&p.kind==='alias'&&ids.has(p.left_id))names.push(p.alias_name);const aliases=[...new Set(names)].filter(n=>norm(n)!==norm(first.title)&&norm(n)!==norm(first.en));return {...first,members,aliases};});
}
function coverCandidates(d){return ['a','b','c','d'].flatMap(k=>(d.members||[d]).filter(m=>m.source===k).map(m=>m.cover)).filter(Boolean);}
function setupCover(img,d){const urls=coverCandidates(d);const placeholder=img.parentElement?.querySelector('.cover-placeholder');let cursor=0;const next=()=>{img.style.opacity='0';if(placeholder)placeholder.hidden=false;if(cursor>=urls.length){img.hidden=true;img.removeAttribute('src');return;}img.hidden=false;const url=urls[cursor++];img.crossOrigin=url.startsWith('https://mztj666.com/')?'anonymous':null;img.src=url;};img.onerror=next;img.onload=()=>{img.hidden=false;img.style.opacity='1';if(placeholder)placeholder.hidden=true;};next();}
const selectedTags=[];
function populateDates(){const source=$('#source-filter').value;const dates=[...new Set(data.filter(r=>!source||r.source===source).map(r=>r.date).filter(d=>/^\d{4}-\d{2}-\d{2}$/.test(d||'')))].sort().reverse();$('#date-options').innerHTML=dates.map(d=>`<option value="${d}"></option>`).join('');const end=$('#date-end'),selected=end.value;end.innerHTML='<option value="same">同一天</option><option value="">至今</option>'+[...new Set([...dates,...(/^\d{4}-\d{2}-\d{2}$/.test(selected)?[selected]:[])])].sort().reverse().map(d=>`<option value="${d}">${d}</option>`).join('');end.value=selected;}
let calendarYear,calendarMonth;
function calendarToday(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const value=Object.fromEntries(parts.map(p=>[p.type,p.value]));return `${value.year}-${value.month}-${value.day}`;}
function closeDateCalendar(){const dialog=$('#date-calendar');if(typeof dialog.close==='function')dialog.close();else dialog.removeAttribute('open');}
function chooseCalendarDay(day){$('#date-filter').value=day;page=1;render();closeDateCalendar();}
function drawDateCalendar(){const current=$('#date-filter').value,today=calendarToday(),source=$('#source-filter').value;const dates=new Set(data.filter(d=>!source||d.source===source).map(d=>d.date));const first=(new Date(calendarYear,calendarMonth,1).getDay()+6)%7,count=new Date(calendarYear,calendarMonth+1,0).getDate();const thisYear=Number(today.slice(0,4));const from=Math.min(2000,calendarYear),to=Math.max(thisYear+5,calendarYear);$('#calendar-year').innerHTML=Array.from({length:to-from+1},(_,i)=>`<option value="${from+i}">${from+i} 年</option>`).join('');$('#calendar-year').value=String(calendarYear);$('#calendar-month').innerHTML=Array.from({length:12},(_,i)=>`<option value="${i}">${i+1} 月</option>`).join('');$('#calendar-month').value=String(calendarMonth);$('#calendar-days').innerHTML=Array.from({length:first},()=>'<span aria-hidden="true"></span>').join('')+Array.from({length:count},(_,i)=>{const day=`${calendarYear}-${String(calendarMonth+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return `<button type="button" data-calendar-day="${day}" class="${dates.has(day)?'has-records ':''}${day===today?'calendar-is-today':''}" aria-label="${day}${dates.has(day)?'，有收录':''}" aria-pressed="${current===day}" ${day===today?'aria-current="date"':''}>${i+1}</button>`;}).join('');document.querySelectorAll('[data-calendar-day]').forEach(b=>b.onclick=()=>chooseCalendarDay(b.dataset.calendarDay));}
function openDateCalendar(){const selected=$('#date-filter').value||calendarToday();calendarYear=Number(selected.slice(0,4));calendarMonth=Number(selected.slice(5,7))-1;drawDateCalendar();const dialog=$('#date-calendar');if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');}
function moveCalendarMonth(delta){const date=new Date(calendarYear,calendarMonth+delta,1);calendarYear=date.getFullYear();calendarMonth=date.getMonth();drawDateCalendar();}
function dateMatches(record){const start=$('#date-filter').value,end=$('#date-end').value==='same'?start:$('#date-end').value;return (!start&&!end)||!!record.date&&(!start||record.date>=start)&&(!end||record.date<=end);}
function recordTags(m){return [...new Set([m.type,...(Array.isArray(m.tags)?m.tags:[])].filter(t=>typeof t==='string'||typeof t==='number').map(t=>String(t).trim()).filter(Boolean))];}
function addSearchTag(tag,source=''){tag=String(tag||'').trim().slice(0,80);if(!tag)return;if(!selectedTags.some(t=>t.source===source&&norm(t.tag)===norm(tag)))selectedTags.push({source,tag});$('#tag-filter').value='';populateTags();page=1;render();}
function populateTags(){const openSites=new Set([...document.querySelectorAll('[data-tag-site][open]')].map(d=>d.dataset.tagSite));$('#tag-groups').innerHTML=['a','b','c','d'].map(source=>{const tags=[...new Set(data.filter(m=>m.source===source).flatMap(recordTags))].sort((a,b)=>a.localeCompare(b,'zh-CN'));return `<details class="tag-site" data-tag-site="${source}" ${openSites.has(source)?'open':''}><summary>${esc(SOURCE_NAMES[source])} · ${tags.length} 个标签</summary><div class="tag-options">${tags.length?tags.map(tag=>`<button type="button" data-source-tag="${source}" data-tag="${esc(tag)}" aria-pressed="${selectedTags.some(t=>t.source===source&&t.tag===tag)}">${esc(tag)}</button>`).join(''):'<span class="count">暂无可用标签</span>'}</div></details>`;}).join('');$('#selected-tags').innerHTML=selectedTags.map((t,i)=>`<button type="button" data-remove-tag="${i}" aria-label="移除标签 ${esc(t.tag)}">${t.source?esc(SOURCE_NAMES[t.source])+'：':''}${esc(t.tag)} ×</button>`).join('');$('#tag-selection-count').textContent=selectedTags.length?'已选 '+selectedTags.length+' 个标签':'选择标签';document.querySelectorAll('[data-source-tag]').forEach(b=>b.onclick=()=>{const at=selectedTags.findIndex(t=>t.source===b.dataset.sourceTag&&t.tag===b.dataset.tag);if(at>=0){selectedTags.splice(at,1);populateTags();page=1;render();}else addSearchTag(b.dataset.tag,b.dataset.sourceTag);});document.querySelectorAll('[data-remove-tag]').forEach(b=>b.onclick=()=>{selectedTags.splice(Number(b.dataset.removeTag),1);populateTags();page=1;render();});}
function matchesCatalogFilters(d){const source=$('#source-filter').value,query=norm($('#tag-filter').value),min=Number($('#min-rating').value)||0;if($('#date-filter').value&&$('#date-end').value&&$('#date-end').value!=='same'&&$('#date-filter').value>$('#date-end').value)return false;return d.members.some(m=>(!source||m.source===source)&&dateMatches(m)&&(!query||recordTags(m).some(t=>norm(t).includes(query)))&&(!selectedTags.length||selectedTags.some(t=>(!t.source||t.source===m.source)&&recordTags(m).some(label=>norm(label).includes(norm(t.tag)))))&&(!min||(m.score&&m.score[0]>=min)));}
function matchesSourceDate(d,source,date){return d.members.some(m=>(!source||m.source===source)&&(!date||m.date===date));}
function scorePreview(d){const short={a:'种花',b:'甜度',c:'喵仔',d:'第七页'};const rated=d.members.filter(m=>m.score);return `<div class="score-preview">${rated.length?rated.map(m=>`<span class="score-pill" data-score-source="${m.source}">${short[m.source]} ★ ${m.score[0].toFixed(1)}</span>`).join(''):'<span class="count">暂无评分</span>'}</div>`;}
function sourceRows(d){return ['a','b','c','d'].map(source=>{const records=d.members.filter(m=>m.source===source);if(!records.length)return $('#show-unmatched').checked?`<div class="row unmatched-row"><div><span class="source-name">${SOURCE_NAMES[source]}</span></div><div class="pending">未匹配到记录</div></div>`:'';return records.map(m=>`<div class="row" data-row-source="${source}"><div><span class="source-name">${SOURCE_NAMES[source]}</span><div class="count">${esc(m.sourceTitle)}</div><div class="count">原站收录日期：${esc(m.date||'未注明')}</div><div class="drama-tags">${recordTags(m).map(t=>`<span class="drama-tag">${esc(t)}</span>`).join('')}</div></div>${m.score?`<div class="score-block"><div class="score">${m.score[0].toFixed(1)} <small>/ 5</small></div><div class="count rating-count">${m.score[1]} 人评分</div></div>`:'<div class="score-block pending">暂无评分</div>'}<div class="jump">${source==='b'&&m.resources?.length?`<a class="link direct-resource" href="/go/${m.linkKey}-resource-0" target="_blank" rel="noopener noreferrer">直接打开资源 · ${esc(m.resources[0].label)}</a>`:''}<a class="link" ${(source==='b'||source==='d')?`data-copy="${m.id}"`:''} href="/go/${m.linkKey}" target="_blank" rel="noopener noreferrer">${(source==='b'||source==='d')?'复制原站剧名并打开':'查看原站剧集'}</a><span class="click-count" data-count="${m.linkKey}">加载次数…</span></div>${m.resources?.length?`<details class="resource-list"><summary>资源入口（${m.resources.length}）</summary><div class="resource-links">${m.resources.map((r,i)=>`<div><a href="/go/${m.linkKey}-resource-${i}" target="_blank" rel="noopener noreferrer">${esc(r.label)}</a><span class="click-count" data-count="${m.linkKey}-resource-${i}">加载次数…</span></div>`).join('')}</div></details>`:''}</div>`).join('');}).join('');}
const SOURCE_NAMES={a:'在云的背面种花',b:'甜度满分小剧院',c:'喵仔的剧集库',d:'风停在第七页 · PageVII'};
function catalogDate(iso){if(!iso)return '未知';return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(iso));}
async function loadCatalog(){try{const r=await fetch('/api/catalog',{cache:'no-store'});if(!r.ok)throw Error();const payload=await r.json();data=payload.items;catalogMeta=payload.meta;catalogLoaded=true;$('#source-status').innerHTML=catalogMeta.sources.map(s=>`<div><strong>${esc(s.name)}</strong> · ${s.count} 条<div class="count">最后成功采集：${catalogDate(s.successAt)}${s.error?' · 本次更新失败，保留旧数据':s.warning?' · '+esc(s.warning):''}</div></div>`).join('');populateDates();populateTags();$('#catalog-notice').textContent='';render();renderProposals();}catch{$('#catalog-notice').textContent='目录加载失败，请刷新重试。';}}
function latestSortKey(group){const source=$('#source-filter').value;const rows=group.members.filter(m=>(!source||m.source===source)&&dateMatches(m));const day=rows.map(r=>r.date||'').sort().at(-1)||'';const current=rows.filter(r=>(r.date||'')===day);const timed=current.filter(r=>Number.isFinite(r.sortAt)&&r.sortAt>0);const preferred=(timed.length?timed:current).slice().sort((a,b)=>timed.length?(b.sortAt-a.sortAt):((a.source||'').localeCompare(b.source||'')||(a.sourceOrder??Number.MAX_SAFE_INTEGER)-(b.sourceOrder??Number.MAX_SAFE_INTEGER)))[0];return {day,time:preferred?.sortAt||0,hasTime:timed.length?1:0,source:preferred?.source||'',order:preferred?.sourceOrder??data.indexOf(preferred)};}
function compareLatest(a,b){const x=latestSortKey(a),y=latestSortKey(b);return y.day.localeCompare(x.day)||y.hasTime-x.hasTime||y.time-x.time||x.source.localeCompare(y.source)||x.order-y.order;}
function aliasPreview(d){return d.aliases.length?`<div class="alias-block"><span class="alias-text" id="aliases-${d.id}">其他名字：${esc(d.aliases.join(' / '))}</span><button class="alias-toggle" data-alias-toggle="${d.id}" aria-expanded="false" aria-controls="aliases-${d.id}">展开</button></div>`:'';}
